<template><main class="stories-page"><header><span>MEMORY STORIES</span><h1>故事航线</h1><p>让文字、照片、地点和音乐沿着同一条时间线展开。</p><NuxtLink to="/journeys">浏览旅行 <Icon name="ph:arrow-right-bold" /></NuxtLink></header><a-spin :spinning="loading"><section v-if="items.length"><NuxtLink v-for="item in items" :key="item.id" :to="`/stories/${item.slug}`"><div class="story-cover"><img v-if="item.coverImage||item.steps[0]?.photo?.path" :src="mediaUrl(item.coverImage||item.steps[0].photo.path)" alt=""><Icon v-else name="ph:star-four-bold" /></div><div><small>{{ item.steps.length }} 个章节</small><h2>{{ item.title }}</h2><p>{{ item.description }}</p><span><Icon name="ph:play-fill" />播放故事</span></div></NuxtLink></section><a-empty v-else-if="!loading" description="故事仍在编排中" /></a-spin></main></template>
<script setup lang="ts">const api=useApi();const {mediaUrl}=useMediaUrl();const loading=ref(true);const items=ref<any[]>([]);onMounted(async()=>{try{items.value=await api.get('/stories')}catch{items.value=[]}finally{loading.value=false}});useHead({title:'故事航线'})</script>
<style scoped>.stories-page{width:min(1080px,calc(100% - 32px));margin:0 auto;padding:50px 0 90px}.stories-page>header{position:relative;margin-bottom:34px}.stories-page>header>span{color:var(--c-primary);font-size:.65rem;font-weight:750}.stories-page h1{margin:8px 0;color:var(--c-text);font-size:2.5rem}.stories-page header p{color:var(--c-text-3)}.stories-page header a{display:inline-flex;align-items:center;gap:5px;color:var(--c-primary);font-size:.75rem;text-decoration:none}.stories-page section{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.stories-page section>a{display:grid;grid-template-columns:45% 1fr;min-height:210px;overflow:hidden;border:1px solid var(--border);border-radius:8px;background:var(--ld-bg-card);color:inherit;text-decoration:none}.story-cover{display:grid;overflow:hidden;background:#172126;color:#ddb05b;font-size:2.5rem;place-items:center}.story-cover img{width:100%;height:100%;object-fit:cover}.stories-page section>a>div:last-child{padding:24px}.stories-page small{color:var(--c-primary)}.stories-page h2{margin:8px 0;color:var(--c-text);font-size:1.15rem}.stories-page section p{color:var(--c-text-3);font-size:.75rem;line-height:1.7}.stories-page section div>span{display:inline-flex;align-items:center;gap:5px;margin-top:10px;color:var(--c-text-2);font-size:.7rem}@media(max-width:760px){.stories-page section{grid-template-columns:1fr}.stories-page section>a{min-height:180px}}</style>
